const raw = $input.first().json || {};

// Error Triggerの出力構造は公式ドキュメントで詳細確認できなかったため、複数の想定パスを防御的に読む。
// [要インスタンス確認][要公式確認]
const workflowName = raw.workflow?.name || raw.workflowData?.name || '[不明なワークフロー]';
const workflowId = raw.workflow?.id || raw.workflowData?.id || null;
const executionId = raw.execution?.id || raw.executionId || null;
const executionUrl = raw.execution?.url || null;
const errorMessage = raw.execution?.error?.message || raw.error?.message || raw.message || '[エラーメッセージ取得不可]';
const failedNodeName = raw.execution?.lastNodeExecuted || raw.error?.node?.name || raw.node?.name || '[不明なノード]';
const mode = raw.execution?.mode || raw.mode || null;

// JSTでの発生時刻表示（Node.jsのICUデータにAsia/Tokyoが含まれることが前提。含まれない実行環境の場合はUTC表記にフォールバック）
let occurredAtJst;
try {
  occurredAtJst = new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
} catch (e) {
  occurredAtJst = new Date().toISOString() + ' (UTC, JST変換失敗)';
}

// 冪等性チェック：同一execution+nodeの組み合わせを一定件数保持し、重複起動を検出する
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedErrorKeys)) {
  staticData.processedErrorKeys = [];
}
const dedupeKey = String(executionId) + '_' + String(failedNodeName);
const isDuplicate = staticData.processedErrorKeys.includes(dedupeKey);
if (!isDuplicate) {
  staticData.processedErrorKeys.push(dedupeKey);
  // 直近200件のみ保持（無限増加防止）
  if (staticData.processedErrorKeys.length > 200) {
    staticData.processedErrorKeys = staticData.processedErrorKeys.slice(-200);
  }
}

return [{
  json: {
    workflowName,
    workflowId,
    executionId,
    executionUrl,
    errorMessage,
    failedNodeName,
    mode,
    occurredAtJst,
    isDuplicate: isDuplicate ? 'true' : 'false'
  }
}];

const d = $input.first().json;

const lines = [
  `【n8nエラー】${d.workflowName}`,
  `発生時刻: ${d.occurredAtJst}`,
  `失敗ノード: ${d.failedNodeName}`,
  `実行ID: ${d.executionId || '不明'}`,
  `エラー: ${d.errorMessage}`,
  '',
  '本通知はn8n共通エラーハンドラー（AUTO-COM-002）による自動送信です。'
];
let text = lines.join('\n');

// LINE公式ドキュメントでtext messageの正確な文字数上限を本調査では確認できなかったため、
// 安全側に1900文字で切り詰める。[要公式確認]
const MAX_LEN = 1900;
if (text.length > MAX_LEN) {
  text = text.slice(0, MAX_LEN - 20) + '\n...(切り詰め)';
}

// Broadcast Message（POST /v2/bot/message/broadcast）は`to`パラメータが不要
// （LINE公式OpenAPI定義 BroadcastRequestスキーマ、2026-08-10参照）。
const lineRequestBody = {
  messages: [
    { type: 'text', text }
  ]
};

return [{ json: { ...d, lineRequestBody } }];

const raw = $input.first().json || {};

// 2026-08-10実機テスト（execution 47）で確認済み：continueOnFail=true時、HTTP Requestノードが
// 失敗するとjsonは{error:{message,name,stack}}のみに置き換わり、それ以前の項目は失われる。
const hasHttpError = Boolean(raw.error) || (typeof raw.statusCode === 'number' && raw.statusCode >= 300);
const lineSendSuccess = !hasHttpError;

// 失敗時に必要な文脈情報（destinationParentPageId・workflowName等）はLINEノードの出力からは
// 失われているため、LINE呼び出し前の「設定：通知先」ノードから明示的に取り直す（実機確認済みの修正）。
const context = $('設定：通知先（Notionフォールバック格納先は暫定値・社長の正式承認は未了）').first().json;

return [{
  json: {
    ...context,
    lineSendSuccess: lineSendSuccess ? 'true' : 'false',
    lineError: hasHttpError ? raw.error : null
  }
}];

const d = $input.first().json;

function chunk(str, size) {
  const out = [];
  for (let i = 0; i < str.length; i += size) out.push(str.slice(i, i + size));
  return out.length ? out : [''];
}

const detailLines = [
  `事業: コホマダ`,
  `カテゴリ: その他`,
  `種別: システムアラート`,
  `発生時刻: ${d.occurredAtJst}`,
  `対象ワークフロー: ${d.workflowName}（ID: ${d.workflowId || '不明'}）`,
  `失敗ノード: ${d.failedNodeName}`,
  `実行ID: ${d.executionId || '不明'}`,
  `実行モード: ${d.mode || '不明'}`,
  `エラーメッセージ: ${d.errorMessage}`,
  '',
  '本通知はn8n共通エラーハンドラー（AUTO-COM-002）による自動記録です（LINE送信失敗時のフォールバック経路）。実際の対応要否・原因調査は人が行ってください。'
];

const children = [];
for (const line of detailLines) {
  for (const part of chunk(line, 1900)) {
    children.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: part } }] } });
  }
}

// parentがpage_id（通常ページの子として作成）の場合、propertiesに指定できるのはtitle型のみ。
// database_id（データベースの行として作成）の場合と異なり、select等のプロパティは指定不可。
// 出典：Notion公式APIドキュメント「Create a page」（https://developers.notion.com/reference/post-page 、2026-08-10参照）
// 2026-08-10実機テスト（execution 49）で確認：プロパティキーに'Name'を使うと
// 'Invalid property identifier Name'で失敗した。parentがpage_id（親がデータベースの行であっても、
// page_id指定で子ページを作る場合は親の行としてではなく通常ページとして扱われる）の場合、
// キー名は親データベースのtitleプロパティ名（'Name'等）ではなく、固定の'title'でなければならない。
const notionRequestBody = {
  parent: { page_id: d.destinationParentPageId },
  properties: {
    'title': { title: [{ text: { content: `【n8nエラー】${d.workflowName} (${d.occurredAtJst})` } }] }
  },
  children
};

return [{ json: { notionRequestBody } }];
